import os

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Settings whose values must never be printed in full (e.g. by `doctor`).
SECRET_KEYS = {"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"}

SOURCE_LABELS = {"env": "environment", ".env": ".env", "default": "default"}


def _parse_value(raw):
    """Turn the right-hand side of a dotenv line into its value.

    Handles single quotes (literal), double quotes (with \\" and \\\\ escapes),
    unquoted values with a trailing ` # comment`, and values containing `=`.
    """
    if raw[:1] in ("'", '"'):
        quote = raw[0]
        chars = []
        i = 1
        while i < len(raw):
            ch = raw[i]
            if quote == '"' and ch == "\\" and i + 1 < len(raw) and raw[i + 1] in ('"', "\\"):
                chars.append(raw[i + 1])
                i += 2
                continue
            if ch == quote:
                return "".join(chars)
            chars.append(ch)
            i += 1
        # Unterminated quote: keep the raw text rather than silently dropping it.
        return raw
    # Unquoted: a `#` preceded by whitespace starts a comment.
    for index, ch in enumerate(raw):
        if ch == "#" and index > 0 and raw[index - 1].isspace():
            return raw[:index].rstrip()
    return raw


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("export") and line[len("export"):len("export") + 1].isspace():
                line = line[len("export"):].lstrip()
            key, sep, raw = line.partition("=")
            key = key.strip()
            if not sep or not key:
                continue
            values[key] = _parse_value(raw.strip())
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config


def describe_value(key, value):
    """Return a display-safe rendering of a setting value."""
    if value is None:
        return "(not set)"
    if key in SECRET_KEYS:
        return f"<redacted, {len(value)} characters>"
    return repr(value)


def doctor_report(config, dotenv_path=".env"):
    """Build the text printed by `python -m payhook doctor`."""
    found = "found" if os.path.exists(dotenv_path) else "not found"
    lines = [
        "payhook configuration",
        f"dotenv file: {os.path.abspath(dotenv_path)} ({found})",
        "",
    ]
    width = max(len(key) for key in config)
    for key, (value, source) in config.items():
        lines.append(
            f"{key.ljust(width)}  {describe_value(key, value)}  "
            f"[source: {SOURCE_LABELS[source]}]"
        )
    return "\n".join(lines)

